// The same actions are used by forms and AI; the server checks the role again on confirmation.
#[component]
fn ActionForm(
    ui: Ui,
    title: &'static str,
    action: &'static str,
    fields: Vec<(&'static str, &'static str, &'static str)>,
) -> impl IntoView {
    let mut initial = json!({"action":action});
    for (k, _, v) in &fields {
        initial[*k] = if matches!(action, "ai_limits" | "shop_update")
            && !ui.state.get_untracked()["shop"][*k].is_null()
        {
            let current = ui.state.get_untracked()["shop"][*k].clone();
            json!(current
                .as_str()
                .map(str::to_string)
                .unwrap_or(current.to_string()))
        } else {
            json!(v)
        };
    }
    let data = RwSignal::new(initial);
    view! {<form class="manage-card form-grid" on:submit=move|e|{e.prevent_default();let mut p=data.get_untracked();for k in ["price","seats","count","start","daily_token_limit","hourly_token_limit","max_output_tokens"]{if let Some(s)=p[k].as_str(){p[k]=if k=="price"{s.parse::<f64>().ok().map(|n|json!((n*100.).round()as i64)).unwrap_or(Value::Null)}else{s.parse::<i64>().ok().map(|n|json!(n)).unwrap_or(Value::Null)};}}if p.get("guid").is_some_and(|v|v==""){p["guid"]=Value::Null;}ui.run("action",p);}>
    <h3>{title}</h3>{fields.into_iter().map(|(key,name,_)|view!{<label>{name}<input prop:value=move||val(&data.get(),key) on:input=move|e|data.update(|d|d[key]=json!(event_target_value(&e)))/></label>}).collect_view()}<button class="primary" type="submit" disabled=move||ui.busy.get()>"Review / 확인"</button></form>}
}
