#[component]
fn LiveTables(ui: Ui) -> impl IntoView {
    view! {<section class="live-tables"><div class="row"><h3>{move||label(ui,"실시간 테이블 현황","Live table service")}</h3><small>"● Live"</small></div>
    <Show when=move||ui.state.get()["simulation"]==true><div class="simulation-controls"><span>{move||format!("{} · {}× · {} min · {} orders",label(ui,"가상 운영","Virtual service"),ui.state.get()["service_simulation"]["speed"],ui.state.get()["service_simulation"]["elapsed"].as_i64().unwrap_or(0)/60,ui.state.get()["service_simulation"]["generated"])}</span><Show when=move||ui.state.get()["role"]=="owner"><select aria-label="Simulation speed" prop:value=move||ui.state.get()["service_simulation"]["speed"].to_string() on:change=move|e|ui.run("simulation_control",json!({"running":ui.state.get_untracked()["service_simulation"]["running"]==true,"speed":event_target_value(&e).parse::<i64>().unwrap_or(1)}))><option value="1">"1×"</option><option value="10">"10×"</option><option value="100">"100×"</option></select><button disabled=move||ui.busy.get() on:click=move |_|ui.run("simulation_control",json!({"running":ui.state.get_untracked()["service_simulation"]["running"]!=true,"speed":ui.state.get_untracked()["service_simulation"]["speed"]}))>{move||if ui.state.get()["service_simulation"]["running"]==true{label(ui,"가상 운영 멈춤","Pause simulation")}else{label(ui,"가상 운영 시작","Start simulation")}}</button></Show></div></Show>
    <div class="table-map" style=move||format!("height:{}px",(((arr(&ui.state.get(),"tables").len()+3)/4)*110).max(430))>{move||arr(&ui.state.get(),"tables").into_iter().filter(|t|t["active"]==true).enumerate().map(|(index,t)|{let orders=arr(&ui.state.get(),"orders").into_iter().filter(|o|o["table"]==t["id"]&&!matches!(o["status"].as_str(),Some("completed"|"cancelled"|"refunded"))).collect::<Vec<_>>();let state=["ready","new","preparing","served"].into_iter().find(|s|orders.iter().any(|o|o["status"]==*s)).unwrap_or("idle");let x=t["x"].as_f64().unwrap_or(14.0+(index%4)as f64*24.0);let y=t["y"].as_f64().unwrap_or((55.0+(index/4)as f64*110.0)/(((arr(&ui.state.get(),"tables").len()+3)/4)*110).max(430)as f64*100.0);view!{<button class=format!("table-node {state}") style=format!("left:{x}%;top:{y}%") on:click=move |_|ui.tab.set("orders".into())><strong>{val(&t,"code")}</strong><small>{format!("{} {}",t["seats"],label(ui,"좌석","seats"))}</small><span>{if state=="idle"{label(ui,"활성 주문 없음","No active orders")}else{ui.tr(state)}}</span><small>{format!("{} {}",t["open_orders"],label(ui,"주문","orders"))}</small></button>}}).collect_view()}</div><p class="helper">{move||label(ui,"주문 상태 기준이며 실제 착석 여부를 감지하지는 않습니다. 사진 배치는 추정도입니다.","Based on order status, not occupancy sensors. Photo-derived positions are schematic.")}</p></section>}
}
#[component]
fn FloorplanStudio(ui: Ui) -> impl IntoView {
    let draft = RwSignal::new(ui.state.get_untracked()["floorplan_draft"].clone());
    view! {<section class="manage-card"><h3>{move||label(ui,"사진으로 테이블 배치 만들기","Create a seating plan from a photo")}</h3><p>{move||label(ui,"AI가 추정 배치를 만듭니다. 실제 치수는 알 수 없으므로 좌석 수와 위치를 검토하세요. 기존 테이블은 삭제하지 않습니다.","AI drafts approximate positions. Review seat counts and positions; this is not a measured floor plan. Existing tables are not deleted.")}</p><input id="floor-photo-input" aria-label="Shop floor photo" type="file" accept="image/*" capture="environment" disabled=move||ui.busy.get()||ui.state.get()["shop"]["agent_running"]!=true||ui.state.get()["simulation"]==true on:change=move |_|{ui.busy.set(true);spawn_local(async move{let result=async{let image=read_floor_photo().await.map_err(error_js)?.as_string().unwrap_or_default();let r=rpc(&ui.token.get_untracked(),"floorplan_draft",json!({"image":image,"language":ui.lang.get_untracked()})).await?;draft.set(r["floorplan"].clone());ui.refresh().await?;Ok::<(),String>(())}.await;if let Err(e)=result{ui.notice.set(e);}ui.busy.set(false);});}/><p class="helper">{move||label(ui,"사진 분석은 Live 모드와 Run이 필요합니다. 사진은 저장하지 않습니다.","Photo analysis requires Live mode and Run. Source photos are not stored.")}</p><button on:click=move |_|draft.set(ui.state.get_untracked()["floorplan_draft"].clone())>{move||label(ui,"최근 AI 초안 불러오기","Load latest AI draft")}</button>
    <Show when=move||draft.get()["tables"].is_array()><p>{move||val(&draft.get(),"notes")}</p><div class="table-map">{move||arr(&draft.get(),"tables").into_iter().map(|t|view!{<div class="table-node draft" style=format!("left:{}%;top:{}%",t["x"],t["y"])><strong>{val(&t,"code")}</strong><small>{format!("{} seats",t["seats"])}</small></div>}).collect_view()}</div>
    {move||(0..arr(&draft.get(),"tables").len()).map(|index|view!{<div class="floor-edit">{["code","seats","x","y"].into_iter().map(|field|view!{<label>{field}<input aria-label=format!("Table {} {field}",index+1) prop:value=move||{let value=draft.get()["tables"][index][field].clone();value.as_str().map(str::to_string).unwrap_or(value.to_string())} on:input=move|e|{let value=event_target_value(&e);draft.update(|d|d["tables"][index][field]=if field=="code"{json!(value)}else if field=="seats"{value.parse::<i64>().map(Value::from).unwrap_or(Value::Null)}else{value.parse::<f64>().map(Value::from).unwrap_or(Value::Null)});}/></label>}).collect_view()}</div>}).collect_view()}
    <button class="primary" disabled=move||ui.busy.get() on:click=move |_|ui.run("action",json!({"action":"floorplan_apply","tables":draft.get_untracked()["tables"]}))>{move||label(ui,"배치 검토 후 적용","Review seating plan")}</button></Show></section>}
}
